CREATE OR REPLACE TABLE __SCHEMA_QUALIFIED__.reservations (
    reservation_id STRING,
    traveler_id STRING,
    hotel_id STRING,
    room_type_id STRING,
    check_in_date DATE,
    check_out_date DATE,
    num_guests INT,
    total_cost_credits DOUBLE,
    status STRING,
    created_at TIMESTAMP_NTZ
)
USING DELTA
TBLPROPERTIES (delta.enableChangeDataFeed = true);

